examples.code:
Column {
    MonarchTextField(
        value = password,
        onValueChange = { password = it },
        label = "Password",
        visualTransformation = PasswordVisualTransformation(),
    )
    ProvideTextStyle(MonarchTheme.typography.caption) {
        MonarchLink(
            text = "Forgot password?",
            onClick = { showsReset = true },
            variant = MonarchLinkVariant.Subtle,
        )
    }
}

MonarchText(
    text = buildAnnotatedString {
        append("Read the ")
        withLink(LinkAnnotation.Url("https://example.com/terms", MonarchLinkDefaults.styles())) {
            append("terms of service")
        }
        append(" before you continue.")
    },
)
